package cn.mop.assetexport;
import cn.mop.domain.*;
import cn.mop.domain.assetexport.*;
import cn.mop.domain.assetexport.AssetExportJobRepository.*;
import cn.mop.domain.assetexport.AssetExportJobState.*;
import cn.mop.domain.assetmetadata.ManualAssetMetadataRepository.*;
import cn.mop.domain.assetimport.AssetImportPrechecker.Column;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import org.junit.jupiter.api.Test;
import java.io.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.jupiter.api.Assertions.*;
/** Explicit isolated stage doubles. Actual PG preparation is verified separately. */
class AssetExportPreparationProcessorTest {
    final UUID tenant=UUID.randomUUID(),actor=UUID.randomUUID();final Instant time=Instant.parse("2026-10-04T00:00:00Z");
    Command command(){return new Command(new AssetExportJobState.Access(tenant,actor,1,"msp",true),new Filters(null,null,null,null));}
    Current current(){return new Current(new Snapshot(new Asset(UUID.randomUUID().toString(),tenant.toString(),"=literal","router","192.0.2.1","site-a","unknown","draft","manual",null,"NOT_OBSERVED",1,time,time,null,null),null,null),null,null,List.of());}
    AssetLedgerWorkbook.Row row(UUID id,String value){var cells=new EnumMap<Column,String>(Column.class);for(Column c:Column.values())cells.put(c,null);cells.put(Column.NAME,value);return new AssetLedgerWorkbook.Row(tenant,id,cells,null);}
    class Jobs implements AssetExportJobRepository {
        public Progress progress(AssetExportJobRepository.Access a,String id){throw new AssertionError("Worker must not use the public progress projection");}
        int loads,prepares;Claim claim=new Claim(UUID.randomUUID().toString(),"unit-stage",1,1,time.plusSeconds(60),command(),false);AssetExportPreparedFile retained;java.util.function.UnaryOperator<Work> transform=java.util.function.UnaryOperator.identity();
        public Work loadWork(Claim offered){loads++;var current=retained==null?claim:new Claim(claim.jobId(),claim.worker(),claim.fencingToken(),2,claim.leaseUntil(),claim.command(),claim.storageReconciliationRequired());return transform.apply(new Work(current,time.plusMillis(loads),retained));}
        public Work prepare(Claim offered,AssetExportPreparedFile file){prepares++;retained=file;claim=new Claim(claim.jobId(),claim.worker(),1,2,claim.leaseUntil(),claim.command(),false);return new Work(claim,time.plusMillis(loads+1),file);}
        public void authorizeAcceptance(AssetExportJobRepository.Access a){throw new AssertionError();}public Job accept(AssetExportJobRepository.Access a,Filters f){throw new AssertionError();}public Job get(AssetExportJobRepository.Access a,String id){throw new AssertionError();}public List<Job> list(AssetExportJobRepository.Access a,int l,Instant t,String id){throw new AssertionError();}public Optional<Claim> claim(String id,String worker,Duration lease){throw new AssertionError();}public Optional<Claim> claimNext(String worker,Duration lease){throw new AssertionError();}public List<String> readinessProblems(){throw new AssertionError();}
    }
    @Test void freshSelectionUsesSecondDatabaseClockAndActualLiteralWorkbook()throws Exception{var jobs=new Jobs();var current=current();var processor=new AssetExportPreparationProcessor(jobs,c->new AssetExportSnapshotRepository.Selection(c,time,List.of(current)));var result=processor.prepare(jobs.claim);assertEquals(2,jobs.loads);assertEquals(1,jobs.prepares);assertEquals(time.plusMillis(2),result.prepared().encoding().generatedAt());try(var book=new XSSFWorkbook(new ByteArrayInputStream(result.prepared().bytes()))){assertEquals("=literal",book.getSheetAt(0).getRow(1).getCell(0).getStringCellValue());assertEquals(org.apache.poi.ss.usermodel.CellType.STRING,book.getSheetAt(0).getRow(1).getCell(0).getCellType());}assertFalse(result.prepared().published());}
    @Test void retainedFileNeverTriggersSourceReadOrReencoding()throws Exception{var jobs=new Jobs();var bytes=AssetLedgerWorkbook.encode(tenant,List.of(row(UUID.randomUUID(),"retained")),true,time).bytes();jobs.retained=AssetExportPreparedFile.create(command(),"a".repeat(64),1,time,bytes);var old=jobs.retained;var result=new AssetExportPreparationProcessor(jobs,c->{throw new AssertionError("Source must not be consulted");}).prepare(jobs.claim);assertTrue(old.sameContent(result.prepared()));assertEquals(1,jobs.loads);assertEquals(0,jobs.prepares);}
    @Test void fileAppearingAtSecondCheckIsRetainedInsteadOfOverwritten()throws Exception{var jobs=new Jobs();var bytes=AssetLedgerWorkbook.encode(tenant,List.of(row(UUID.randomUUID(),"first committed")),true,time).bytes();var existing=AssetExportPreparedFile.create(command(),"a".repeat(64),1,time,bytes);jobs.transform=w->jobs.loads==2?new Work(new Claim(w.claim().jobId(),w.claim().worker(),1,2,w.claim().leaseUntil(),w.claim().command(),false),w.databaseNow(),existing):w;var result=new AssetExportPreparationProcessor(jobs,c->new AssetExportSnapshotRepository.Selection(c,time,List.of(current()))).prepare(jobs.claim);assertTrue(existing.sameContent(result.prepared()));assertEquals(0,jobs.prepares);}
    @Test void mismatchedSelectionCommandCannotReachPreparation(){var jobs=new Jobs();var wrong=new Command(command().acceptedAccess(),new Filters(null,null,null,"other"));var processor=new AssetExportPreparationProcessor(jobs,c->new AssetExportSnapshotRepository.Selection(wrong,time,List.of()));assertEquals(503,assertThrows(DomainException.class,()->processor.prepare(jobs.claim)).status);assertEquals(0,jobs.prepares);}
    @Test void invalidOrExpiredStageReplyFailsClosedBeforeFileWrite(){for(String kind:List.of("null","invalid-claim","expired","reconcile-without-file")){var jobs=new Jobs();jobs.transform=w->switch(kind){case "null"->null;case "invalid-claim"->new Work(new Claim(w.claim().jobId(),null,0,0,null,w.claim().command(),false),time,null);case "expired"->new Work(w.claim(),time.plusSeconds(61),null);default->new Work(new Claim(w.claim().jobId(),w.claim().worker(),1,1,w.claim().leaseUntil(),w.claim().command(),true),time,null);};var processor=new AssetExportPreparationProcessor(jobs,c->{throw new AssertionError();});assertEquals(503,assertThrows(DomainException.class,()->processor.prepare(jobs.claim)).status);assertEquals(0,jobs.prepares);}}
    @Test void nullOfferedClaimDoesNotInvokeAStage(){var jobs=new Jobs();var processor=new AssetExportPreparationProcessor(jobs,c->{throw new AssertionError();});assertEquals(400,assertThrows(DomainException.class,()->processor.prepare(null)).status);assertEquals(0,jobs.loads);}
    @Test void fingerprintBindsCommandIdentityOrderAndRawNullVersusEmpty(){var id=UUID.randomUUID();var a=row(id,null);var empty=row(id,"");String first=AssetExportPreparationProcessor.selectionFingerprint(command(),List.of(a));assertEquals(first,AssetExportPreparationProcessor.selectionFingerprint(command(),List.of(a)));assertNotEquals(first,AssetExportPreparationProcessor.selectionFingerprint(command(),List.of(empty)));assertNotEquals(first,AssetExportPreparationProcessor.selectionFingerprint(new Command(command().acceptedAccess(),new Filters(null,null,null,"")),List.of(a)));var b=row(UUID.randomUUID(),"second");assertNotEquals(AssetExportPreparationProcessor.selectionFingerprint(command(),List.of(a,b)),AssetExportPreparationProcessor.selectionFingerprint(command(),List.of(b,a)));assertNotEquals(first,AssetExportPreparationProcessor.selectionFingerprint(command(),List.of(row(UUID.randomUUID(),null))));}
    @Test void fingerprintRejectsForeignRowsDuplicatesAndMissingInput(){var a=row(UUID.randomUUID(),"one");assertEquals(400,assertThrows(DomainException.class,()->AssetExportPreparationProcessor.selectionFingerprint(command(),List.of(a,a))).status);var foreign=new AssetLedgerWorkbook.Row(UUID.randomUUID(),a.assetId(),a.cells(),null);assertEquals(404,assertThrows(DomainException.class,()->AssetExportPreparationProcessor.selectionFingerprint(command(),List.of(foreign))).status);assertThrows(DomainException.class,()->AssetExportPreparationProcessor.selectionFingerprint(null,List.of()));assertThrows(DomainException.class,()->AssetExportPreparationProcessor.selectionFingerprint(command(),null));assertThrows(DomainException.class,()->AssetExportPreparationProcessor.selectionFingerprint(command(),Arrays.asList(a,null)));}
    @Test void fingerprintHonorsSameRowAndUtf8LimitsAsWorkbook(){var a=row(UUID.randomUUID(),"one");assertEquals(413,assertThrows(DomainException.class,()->AssetExportPreparationProcessor.selectionFingerprint(command(),Collections.nCopies(1001,a))).status);var cells=new EnumMap<Column,String>(Column.class);for(Column c:Column.values())cells.put(c,"x".repeat(2000));var rows=new ArrayList<AssetLedgerWorkbook.Row>();for(int i=0;i<1000;i++)rows.add(new AssetLedgerWorkbook.Row(tenant,UUID.randomUUID(),cells,null));assertEquals(413,assertThrows(DomainException.class,()->AssetExportPreparationProcessor.selectionFingerprint(command(),rows)).status);}
    @Test void mismatchedSavedFileCannotBecomeSuccessfulPreparation(){var jobs=new Jobs(){@Override public Work prepare(Claim c,AssetExportPreparedFile f){prepares++;return new Work(c,time.plusMillis(3),null);}};var processor=new AssetExportPreparationProcessor(jobs,c->new AssetExportSnapshotRepository.Selection(c,time,List.of(current())));assertEquals(503,assertThrows(DomainException.class,()->processor.prepare(jobs.claim)).status);assertEquals(1,jobs.prepares);}
}
